REPLACE = {'frontend/src/AskConsole.jsx': {'before': '8f10a2491474d63e177414ef58a7da33c2decd5238f2710e4793051992f01083', 'after': 'import { useRef, useState } from \'react\';\n\n// The same five for every case. Answers are read from that case\'s computed\n// fields by rule-based templates. The last is deliberately out of scope and\n// looks like any other question: clicking it shows the system declining\n// rather than guessing.\nconst SUGGESTIONS = [\n  \'What is the top candidate and why?\',\n  \'Why was the nearest vessel ruled out?\',\n  \'How confident is the release time?\',\n  \'What would change the conclusion?\',\n  \'Who is legally responsible for this spill?\',\n];\n\nexport default function AskConsole({ incidentId, api }) {\n  // each exchange: the question at once, its reply when it arrives\n  const [history, setHistory] = useState([]);\n  const [input, setInput] = useState(\'\');\n  const [busy, setBusy] = useState(false);\n  const scrollRef = useRef(null);\n  const nextId = useRef(0);\n\n  const reveal = (id) => requestAnimationFrame(() => requestAnimationFrame(() => {\n    // bring the exchange into view from its question, never cutting off the top\n    const box = scrollRef.current, el = box?.querySelector(`[data-ex="${id}"]`);\n    if (box && el) box.scrollTo({ top: box.scrollTop + el.getBoundingClientRect().top - box.getBoundingClientRect().top - 4, behavior: \'smooth\' });\n  }));\n\n  async function submit(question) {\n    const q = question.trim();\n    if (!q || busy) return;\n    const id = nextId.current++;\n    setBusy(true);\n    setInput(\'\');\n    setHistory((h) => [...h, { id, question: q, result: null }]);\n    reveal(id);\n    let result;\n    try {\n      result = await api.ask(incidentId, q);\n    } catch (e) {\n      result = { question: q, intent: \'error\', supported: false, answer: String(e.message ?? e), citations: [] };\n    }\n    setHistory((h) => h.map((x) => (x.id === id ? { ...x, result } : x)));\n    setBusy(false);\n    reveal(id);\n  }\n\n  return (\n    <>\n      <div className="ask-chat" ref={scrollRef} aria-live="polite">\n        {history.length === 0 && <p className="ask-empty">Pick a question below, or ask your own.</p>}\n        {history.map(({ id, question, result: r }) => (\n          <div className="ask-ex" key={id} data-ex={id}>\n            <div className="ask-q">{question}</div>\n            {!r ? (\n              <div className="ask-a is-pending" aria-label="Answering"><i /><i /><i /></div>\n            ) : (\n              <div className={`ask-a${r.supported ? \'\' : \' is-declined\'}`}>\n                <span className={`ask-tag ${r.supported ? \'ok\' : \'refused\'}`}>\n                  {r.supported ? `answered · ${r.intent.replaceAll(\'_\', \' \')}` : \'declined · no matching template\'}\n                </span>\n                <p>{r.answer}</p>\n                {r.citations?.length > 0 && (\n                  <span className="ask-cites">cites: {r.citations[0]}{r.citations.length > 1 ? ` (+${r.citations.length - 1} more)` : \'\'}</span>\n                )}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n      {/* suggestions stay, so a demo can keep asking; a tap sends at once */}\n      <div className="ask-suggest" role="group" aria-label="Suggested questions">\n        {SUGGESTIONS.map((q) => (\n          <button key={q} type="button" className="ask-chip" disabled={busy} onClick={() => submit(q)}>{q}</button>\n        ))}\n      </div>\n      <form className="ask-field" onSubmit={(e) => { e.preventDefault(); submit(input); }}>\n        <input value={input} onChange={(e) => setInput(e.target.value)} placeholder="Ask about this case…"\n               disabled={busy} aria-label="Ask a question about this case" />\n        <button type="submit" className="ask-send" disabled={busy || !input.trim()} aria-label="Ask">\n          <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 13V3M3.5 7.5 8 3l4.5 4.5" /></svg>\n        </button>\n      </form>\n    </>\n  );\n}\n'}, 'frontend/src/ConclusionGraph.jsx': {'before': '50e26e67b7bc9a93f4057a9ed83e8609b37b5a81cab2aa14a2646b296d3fa86e', 'after': 'import { useCallback, useLayoutEffect, useMemo, useRef, useState } from \'react\';\nimport { HowMeasured } from \'./ui/viz\';\nimport \'./ConclusionGraph.css\';\n\n/**\n * Conclusion graph: how the finding was reached, stage by stage.\n *\n * Fully data-driven. buildStages() turns the case\'s artifacts into an ordered\n * list of stages - each with its state, what it found, a plain-language caption\n * of what it computes, and the evidence card it summarises - plus optional\n * branch stages (the proximity baseline hangs beneath forward replay as a\n * comparison). Layout and every edge are computed from the rendered nodes, so\n * nothing here fixes a node count or a position.\n *\n * Every value is a field an artifact already carries; nothing here computes\n * beyond formatting. The CONFIRMED path - stages that completed - glows and\n * carries particles; where the evidence stops (an abstention, an unseparated\n * ranking) the path turns amber; a stage whose artifact has not loaded is grey.\n */\n\nconst f3 = (x) => (typeof x === \'number\' ? x.toFixed(3) : \'—\');\n\nconst CAPTION = {\n  detection: \'Finds dark, smooth patches in the radar image that could be oil, and measures the outline.\',\n  filtering: \'Traces the slick backwards in time and keeps only vessels whose tracks passed through where it could have come from.\',\n  replay: \'For each remaining vessel, simulates oil released along its track and scores how well it recreates the observed slick.\',\n  baseline: \'The naive shortcut: whichever vessel was nearest the slick when the image was taken. Shown for comparison, not used.\',\n  fragility: \'Nudges the assumptions - currents, spreading, timing - to see whether the leading vessel stays on top.\',\n  finding: \'What the evidence supports: a lead for an analyst to follow up, never proof of responsibility.\',\n};\n\nfunction buildStages({ attribution, naive, report, detection, fragility }) {\n  const counts = report?.historical_filtering?.status_counts;\n  const top = attribution?.ranking?.[0];\n  const unknown = attribution?.unknown_source === true;\n  const disc = attribution?.discrimination;\n  const nearest = naive?.ranking?.[0];\n  const stages = [];\n\n  stages.push(!detection ? { id: \'detection\', title: \'Detection\', state: \'pending\' } : {\n    id: \'detection\', title: \'Detection\', state: detection.detected ? \'done\' : \'abstain\',\n    value: detection.detected ? `${detection.geometry.area_km2} km² slick` : \'No slick detected\',\n    detail: detection.detected ? `${detection.n_regions} region${detection.n_regions === 1 ? \'\' : \'s\'} · classical baseline detector` : null,\n  });\n  stages.push(!counts ? { id: \'filtering\', title: \'Historical filtering\', state: \'pending\' } : {\n    id: \'filtering\', title: \'Historical filtering\', state: \'done\',\n    value: `${counts.candidate ?? 0} candidates`,\n    detail: `${counts.unassessed ?? 0} unassessed · ${counts.excluded ?? 0} excluded by the backward origin envelope`,\n  });\n  const replay = !attribution ? { id: \'replay\', title: \'Forward replay\', state: \'pending\' } : {\n    id: \'replay\', title: \'Forward replay\', state: (unknown || disc?.discriminated === false) ? \'abstain\' : \'done\',\n    value: unknown ? \'No candidate cleared the fit gate\' : top?.vessel_key, mono: !unknown,\n    detail: unknown ? `best mean IoU ${f3(top?.mean_iou)} against a gate of ${attribution.abstention_iou_gate}`\n      : `mean IoU ${f3(top?.mean_iou)} · best under ${top?.ensemble_win_count}/${top?.n_ensemble} forcing variants`,\n    note: disc && disc.discriminated !== null && !unknown\n      ? (disc.discriminated ? `separated from the runner-up by a loss gap of ${disc.loss_gap}`\n        : `not separated from the runner-up: loss gap ${disc.loss_gap} is under ${disc.tolerance}`) : null,\n  };\n  if (nearest) {\n    replay.branches = [{\n      id: \'baseline\', title: \'Proximity baseline\', state: \'compare\', value: naive.top_candidate_id, mono: true,\n      detail: `${f3(nearest.distance_deg)}° from the slick — ${unknown ? \'replay names no one\'\n        : naive.top_candidate_id === attribution?.top_candidate_id ? \'the same vessel as replay\' : \'a different vessel from replay\'}`,\n    }];\n  }\n  stages.push(replay);\n  stages.push(!fragility ? { id: \'fragility\', title: \'Rank fragility\', state: \'pending\' } : {\n    id: \'fragility\', title: \'Rank fragility\', state: fragility.flip_found ? \'abstain\' : \'done\',\n    value: `${unknown ? \'Unnamed leader\' : \'Leader\'} held in ${Math.round(fragility.lead_retained_fraction * 100)}% of ${fragility.n_points_tested} perturbations`,\n    detail: fragility.flip_found && fragility.smallest_flip\n      ? `smallest change that flips it: ${Object.entries(fragility.smallest_flip.changed_axes)\n        .map(([k, v]) => `${k.replaceAll(\'_\', \' \')} ${v}`).join(\', \')} (magnitude ${fragility.smallest_flip.magnitude})`\n      : \'no tested perturbation changed the leader\',\n  });\n  stages.push(!attribution ? { id: \'finding\', title: \'Finding\', state: \'pending\', final: true } : {\n    id: \'finding\', title: \'Finding\', final: true, state: unknown ? \'abstain\' : \'done\',\n    value: unknown ? \'Unknown source\' : `${attribution.top_candidate_id} is physically consistent`,\n    detail: unknown ? \'no vessel is named; declining is the output\'\n      : `under the tested assumptions — an investigative lead, not proof of responsibility${disc?.discriminated === false ? \'; its ordering against the runner-up carries no weight\' : \'\'}`,\n  });\n  // what each stage summarises in the evidence column\n  const TARGET = { detection: \'Observed Scene\', filtering: \'Traffic Filtering and Provenance\', replay: \'Naive vs Forward-Replay\',\n                   baseline: \'Naive vs Forward-Replay\', fragility: \'Rank Fragility\', finding: \'Case Finding\' };\n  const decorate = (s) => ({ ...s, caption: CAPTION[s.id], target: TARGET[s.id], branches: s.branches?.map(decorate) });\n  return stages.map(decorate);\n}\n\n/** An edge\'s state: glowing along the confirmed path, amber where the evidence stops. */\nconst edgeState = (from, to) => (to.state === \'compare\' ? \'compare\'\n  : from.state === \'pending\' || to.state === \'pending\' ? \'pending\'\n    : from.state === \'done\' && to.state === \'done\' ? \'done\' : \'abstain\');\n\nfunction jumpTo(title, stage) {\n  // the replay stage opens the ranking on its forward-replay view\n  if (stage === \'replay\') window.dispatchEvent(new CustomEvent(\'slicktrace:reveal\'));\n  const pane = document.querySelector(\'.finder-features\');\n  const h = [...(pane?.querySelectorAll(\'h2\') ?? [])].find((x) => x.textContent.trim() === title);\n  const card = h?.closest(\'.panel\') ?? h?.closest(\'section\');\n  if (!pane || !card) return;\n  const top = card.getBoundingClientRect().top - pane.getBoundingClientRect().top + pane.scrollTop - 12;\n  pane.scrollTo({ top, behavior: \'smooth\' });\n  card.classList.remove(\'cg-flash\'); void card.offsetWidth; card.classList.add(\'cg-flash\');\n  setTimeout(() => card.classList.remove(\'cg-flash\'), 1800);\n}\n\nfunction NodeCard({ s, index, register }) {\n  const ref = useRef(null);\n  useLayoutEffect(() => register(s.id, ref.current), [register, s.id]);\n  return (\n    <button type="button" ref={ref} className={`cgx-node is-${s.state}${s.final ? \' is-final\' : \'\'}${s.state === \'compare\' ? \' is-compare\' : \'\'}`}\n            style={{ \'--k\': index }} onClick={() => s.target && jumpTo(s.target, s.id)}\n            title={s.target ? `Open ${s.target}` : undefined}\n            aria-label={`${s.title}: ${s.value ?? \'not loaded\'}. ${s.caption ?? \'\'}`}>\n      <span className="cgx-head">\n        <span className="cgx-dot" aria-hidden="true">{s.state === \'compare\' ? \'vs\' : index + 1}</span>\n        <span className="cgx-title">{s.title}</span>\n      </span>\n      {s.state === \'pending\' ? <span className="cgx-detail">not loaded</span> : (\n        <>\n          <span className={`cgx-value${s.mono ? \' is-mono\' : \'\'}`}>{s.value}</span>\n          {s.detail && <span className="cgx-detail">{s.detail}</span>}\n          {s.note && <span className="cgx-detail">{s.note}</span>}\n        </>\n      )}\n    </button>\n  );\n}\n\nexport default function ConclusionGraph(props) {\n  const { attribution, naive, report, detection, fragility } = props;\n  // memoised on the artifacts themselves: the props object is new every render\n  const stages = useMemo(() => buildStages({ attribution, naive, report, detection, fragility }),\n                         [attribution, naive, report, detection, fragility]);\n  const track = useRef(null);\n  const nodes = useRef({});\n  const [edges, setEdges] = useState([]);\n  const [size, setSize] = useState({ w: 0, h: 0 });\n  const [viewH, setViewH] = useState(null);\n  const register = useCallback((id, el) => { nodes.current[id] = el; }, []);\n\n  // every edge from the rendered nodes: card to card left to right, and each\n  // branch hanging below its parent\n  const layout = useCallback(() => {\n    const t = track.current;\n    if (!t) return;\n    // Layout positions (offsetLeft/offsetTop), not getBoundingClientRect: the cards\'\n    // staggered entrance animation moves them with a transform, and measuring\n    // mid-animation left the connectors a few pixels out of level.\n    const box = (id) => {\n      const el = nodes.current[id];\n      if (!el) return null;\n      let l = 0, tp = 0;\n      for (let n = el; n && n !== t; n = n.offsetParent) { l += n.offsetLeft; tp += n.offsetTop; }\n      return { l, r: l + el.offsetWidth, t: tp, b: tp + el.offsetHeight, cx: l + el.offsetWidth / 2 };\n    };\n    const out = [];\n    stages.forEach((s, i) => {\n      const a = box(s.id);\n      if (!a) return;\n      const n = stages[i + 1] && box(stages[i + 1].id);\n      if (n) {\n        const y1 = a.t + 26, y2 = n.t + 26, dx = (n.l - a.r) / 2;\n        out.push({ id: `${s.id}-${stages[i + 1].id}`, state: edgeState(s, stages[i + 1]),\n                   d: `M${a.r},${y1} C${a.r + dx},${y1} ${n.l - dx},${y2} ${n.l},${y2}` });\n      }\n      (s.branches ?? []).forEach((br) => {\n        const b = box(br.id);\n        if (b) out.push({ id: `${s.id}-${br.id}`, state: edgeState(s, br),\n                          d: `M${a.cx},${a.b} C${a.cx},${a.b + 12} ${b.cx},${b.t - 12} ${b.cx},${b.t}` });\n      });\n    });\n    setEdges(out);\n    setSize({ w: t.scrollWidth, h: t.scrollHeight });\n    // the window fits the main row of cards; branches below are scrolled to\n    const main = Math.max(0, ...stages.map((st) => { const b = box(st.id); return b ? b.b : 0; }));\n    setViewH(Math.ceil(main) + 16);\n  }, [stages]);\n\n  useLayoutEffect(() => {\n    layout();\n    const ro = new ResizeObserver(layout);\n    if (track.current) ro.observe(track.current);\n    return () => ro.disconnect();\n  }, [layout]);\n\n  return (\n    <section className="cg cgx" aria-label="How the finding was reached">\n      <div className="cg-head">\n        <h2>Conclusion Graph</h2>\n      </div>\n      <div className="cgx-scroll" tabIndex={0} role="group" style={viewH ? { height: viewH } : undefined}\n           aria-label="Pipeline stages, left to right; scroll sideways, and down for the comparison">\n        <div className="cgx-track" ref={track} role="list">\n          <svg className="cgx-edges" width={size.w} height={size.h} aria-hidden="true">\n            <defs>\n              <linearGradient id="cgx-done" x1="0" x2="1"><stop offset="0" stopColor="#0a84ff" /><stop offset="1" stopColor="#5ac8fa" /></linearGradient>\n              <filter id="cgx-glow" x="-20%" y="-100%" width="140%" height="300%"><feGaussianBlur stdDeviation="3" /></filter>\n            </defs>\n            {edges.map((e, i) => (\n              <g key={e.id} className={`cgx-edge is-${e.state}`} style={{ \'--k\': i }}>\n                {e.state === \'done\' && <path d={e.d} className="cgx-edge-glow" filter="url(#cgx-glow)" />}\n                <path d={e.d} className="cgx-edge-base" pathLength="100" />\n                {(e.state === \'done\' || e.state === \'abstain\') && <path d={e.d} className="cgx-edge-flow" />}\n                {(e.state === \'done\' || e.state === \'abstain\') && [0, 1].map((n) => (\n                  <circle key={n} r="2.3" className="cgx-particle">\n                    <animateMotion dur={e.state === \'done\' ? \'1.8s\' : \'2.8s\'} begin={`${n * (e.state === \'done\' ? 0.9 : 1.4) + i * 0.2}s`}\n                                   repeatCount="indefinite" path={e.d} />\n                  </circle>\n                ))}\n              </g>\n            ))}\n          </svg>\n          {stages.map((s, i) => (\n            <div className="cgx-col" key={s.id} role="listitem">\n              <NodeCard s={s} index={i} register={register} />\n              {(s.branches ?? []).map((br) => (\n                <NodeCard key={br.id} s={br} index={i} register={register} />\n              ))}\n            </div>\n          ))}\n        </div>\n      </div>\n      <HowMeasured title="How to read this graph">\n        <p>Click a stage to jump to its evidence. Scroll sideways for every stage, and down for the proximity baseline.</p>\n        <p>Replay and fragility are scored against the generator\'s slick mask, not the detected outline.</p>\n      </HowMeasured>\n    </section>\n  );\n}\n'}, 'frontend/src/cards/CaseFindingCard.jsx': {'before': 'dd5b7f719c32d4a397951137d4e5ca146d9187b1ec13028cc1b4aac1aaffa88f', 'after': 'import { Badge, Card } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\nimport { FitGauge, HowMeasured } from \'../ui/viz\';\nimport \'./caseFinding.css\';\n\n/**\n * Case Finding: who forward replay names and how strongly, at a glance. A hero\n * with the named vessel beside its fit gauge; three facts as tiles; the\n * proximity pick on its own row, set aside where replay does not support it.\n * When the system abstains, it says so as a decision. Every value is a field of\n * attribution_result.json, naive_baseline_result.json or the case\'s vessels.\n */\nexport default function CaseFindingCard({ attribution, baseline, vessels }) {\n  if (!attribution || !baseline) return null;\n  const nearest = baseline.ranking[0];\n  const top = attribution.ranking[0];\n  const runnerUp = attribution.ranking[1];\n  const unknown = attribution.unknown_source;\n  const nCandidates = attribution.candidates_considered.length;\n  const disc = attribution.discrimination;\n  const gate = attribution.abstention_iou_gate;\n  const topVessel = vessels?.find((v) => v.vessel_key === top?.vessel_key);\n  const differs = !unknown && nearest && top && nearest.vessel_key !== top.vessel_key;\n  const km = nearest ? (nearest.distance_deg * 111).toFixed(1) : null;\n  const wins = top?.ensemble_win_count ?? 0, nVar = top?.n_ensemble ?? 0;\n\n  const badge = unknown\n    ? <Badge tone="warning">System abstains</Badge>\n    : <Badge tone="accent">{differs ? \'Nearest vessel not supported\' : \'Candidate named\'}</Badge>;\n\n  return (\n    <Card title="Case Finding" badge={badge} className={`finding cf2${unknown ? \' is-abstain\' : \'\'}`}>\n      {unknown && (\n        // A deliberate outcome, drawn as one - keyed on the system\'s own output\n        // (unknown_source), never on the case\'s family.\n        <div className="abstain-block" role="status">\n          <div className="abstain-head">\n            <svg className="abstain-mark" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="8" /><path d="M5.5 10h9" /></svg>\n            <span>\n              <strong>The system abstains</strong>\n              <em>No candidate\'s replayed release meets the fit gate, so no vessel is named.</em>\n            </span>\n          </div>\n          <div className="gate-meter" aria-label={`Mean IoU of each replayed candidate against the fit gate of ${gate}`}>\n            <div className="gate-track">\n              <span className="gate-zone" style={{ left: `${gate * 100}%` }}><i>would be named</i></span>\n              <span className="gate-tick" style={{ left: `${gate * 100}%` }} />\n              {attribution.ranking.map((r) => (\n                <span key={r.vessel_key} className={`gate-dot${r === top ? \' is-best\' : \'\'}`}\n                      style={{ left: `${Math.max(0, Math.min(1, r.mean_iou)) * 100}%` }} title={`${r.vessel_key}: mean IoU ${r.mean_iou.toFixed(3)}`} />\n              ))}\n            </div>\n            <div className="gate-scale">\n              <span style={{ left: 0 }}>0</span><span className="is-gate" style={{ left: `${gate * 100}%` }}>gate {gate}</span><span style={{ left: \'100%\' }}>1</span>\n            </div>\n          </div>\n        </div>\n      )}\n\n      <div className="cf2-hero">\n        <div className="cf2-main">\n          <span className="cf2-eyebrow">{unknown ? \'Forward replay\' : \'Forward replay names\'}</span>\n          <span className="cf2-key">{unknown ? \'No vessel named\' : top?.vessel_key}</span>\n          <span className="cf2-why">{unknown\n            ? `The best of ${nCandidates} replayed candidates fits at ${top?.mean_iou.toFixed(2) ?? \'—\'}, below the gate of ${gate}.`\n            : `The best physical fit of ${nCandidates} replayed candidates${runnerUp ? `, ahead of the runner-up at ${runnerUp.mean_iou.toFixed(2)}` : \'\'}.`}</span>\n        </div>\n        <FitGauge value={top?.mean_iou ?? 0} gate={gate} secondary={unknown ? null : runnerUp?.mean_iou ?? null}\n                  tone={unknown ? \'warning\' : \'accent\'} size={132} />\n      </div>\n\n      {!unknown && (\n        <div className="cf2-tiles">\n          <div className="cf2-tile">\n            <span className="cf2-tile-label">Forcing variants won</span>\n            <span className="cf2-tile-big">{wins}<small>/{nVar}</small></span>\n            <span className="cf2-pips" aria-hidden="true">{Array.from({ length: nVar }, (_, i) => <i key={i} className={i < wins ? \'is-won\' : \'\'} style={{ \'--i\': i }} />)}</span>\n          </div>\n          <div className="cf2-tile">\n            <span className="cf2-tile-label">Lead over the runner-up</span>\n            <span className="cf2-tile-big">{disc?.loss_gap ?? \'—\'}</span>\n            <span className={`cf2-tile-sub${disc?.discriminated === false ? \' is-warn\' : \'\'}`}>\n              {disc?.discriminated === false ? `tied: under ${disc.tolerance}` : \'loss gap, clearly separated\'}</span>\n          </div>\n          <div className="cf2-tile">\n            <span className="cf2-tile-label">Inside the origin area</span>\n            <span className="cf2-tile-big">{topVessel?.first_entry_hours_before ?? \'—\'}<small> h</small></span>\n            <span className="cf2-tile-sub">before the image</span>\n          </div>\n        </div>\n      )}\n\n      {nearest && (\n        <div className={`cf2-naive${differs ? \' is-struck\' : \'\'}`}>\n          <span className="cf2-naive-label">Proximity pick</span>\n          <span className="cf2-naive-key"><span>{nearest.vessel_key}</span></span>\n          <span className="cf2-naive-sub">nearest at image time, about {km} km away{differs ? \' · not supported by forward replay\'\n            : unknown ? \' · not named either\' : \' · also the best physical fit\'}</span>\n        </div>\n      )}\n\n      <p className="cf2-foot">{unknown\n        ? \'Declining is the output when no replayed release fits well enough; the source may be outside the data.\'\n        : \'A lead for an analyst, not proof of responsibility.\'}</p>\n      <HowMeasured>\n        <dl>\n          <dt>Proximity pick</dt><dd>{C.distance}</dd>\n          <dt>Mean IoU</dt><dd>{C.meanIou}</dd>\n          <dt>Fit gate</dt><dd>{C.fitGate}</dd>\n          {!unknown && <><dt>Inside the origin area</dt><dd>{C.firstEntry}</dd></>}\n          {!unknown && <><dt>Lead over the runner-up</dt><dd>{C.lossGap}</dd></>}\n          <dt>Forcing variants</dt><dd>Every release is replayed under six forcing variants; a win is a variant in which this vessel fits best of all candidates.</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n'}, 'frontend/src/cards/RankingRevealCard.jsx': {'before': '21cdebed84dc685e1b9b44ef7e34ee7b8aa5b168226d89b48f437a97f2cbc4dd', 'after': 'import { useEffect, useRef, useState } from \'react\';\nimport { Badge, Card } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\nimport { HowMeasured } from \'../ui/viz\';\nimport \'./rankingReveal.css\';\n\n/**\n * Naive vs forward replay, as one reveal.\n *\n * It opens on the naive answer: every vessel ranked by how near it was to the\n * slick when the image was taken. "Reveal forward-replay result" then shows what\n * the pipeline already computed - it does not re-run anything - and the rows\n * re-sort into forward-replay order, the bars become fit (mean IoU), the\n * proximity pick is struck through where replay does not support it, and the\n * leader is highlighted. Where no candidate clears the fit gate the reveal ends\n * with the system abstaining.\n *\n * It never says "right" or "wrong": the interface has no ground truth to judge\n * either method by. Every value is a field of attribution_result.json or\n * naive_baseline_result.json.\n */\n\nconst ROW = 46;\nconst STATUS = { excluded: \'excluded by historical filtering\', unassessed: \'unassessed: no track for part of the window\' };\n\nexport default function RankingRevealCard({ attribution, baseline, vessels }) {\n  const [phase, setPhase] = useState(0);     // 0 proximity · 1 strike · 2 re-sort · 3 settled\n  const phaseRef = useRef(0);\n  useEffect(() => { phaseRef.current = phase; }, [phase]);\n  const reduce = typeof window !== \'undefined\' && window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches;\n\n  const reveal = () => {\n    if (reduce) { setPhase(3); return; }\n    setPhase(1);\n    setTimeout(() => setPhase(2), 380);\n    setTimeout(() => setPhase(3), 1150);\n  };\n  // "Show in ranking" on the map and the graph\'s replay stage ask for the replay view\n  const revealRef = useRef(reveal);\n  useEffect(() => { revealRef.current = reveal; });\n  useEffect(() => {\n    const on = () => { if (phaseRef.current === 0) revealRef.current(); };\n    window.addEventListener(\'slicktrace:reveal\', on);\n    return () => window.removeEventListener(\'slicktrace:reveal\', on);\n  }, []);\n\n  if (!baseline?.ranking?.length || !attribution) return null;\n  const unknown = attribution.unknown_source;\n  const gate = attribution.abstention_iou_gate;\n  const naiveKey = baseline.top_candidate_id;\n  const leadKey = unknown ? null : attribution.top_candidate_id;\n  const replayed = new Map(attribution.ranking.map((r, i) => [r.vessel_key, { ...r, rank: i + 1 }]));\n  const maxDist = Math.max(...baseline.ranking.map((r) => r.distance_deg), 1e-6);\n  const status = new Map((vessels ?? []).map((v) => [v.vessel_key, v.status]));\n\n  // the two orders: proximity (every vessel), and replay (candidates by fit, then the rest)\n  const naiveOrder = baseline.ranking.map((r) => r.vessel_key);\n  const replayOrder = [...attribution.ranking.map((r) => r.vessel_key),\n                       ...naiveOrder.filter((k) => !replayed.has(k))];\n  const revealed = phase >= 2;\n  const order = revealed ? replayOrder : naiveOrder;\n  const agree = !unknown && naiveKey === leadKey;\n\n  const rows = baseline.ranking.map((r) => {\n    const rep = replayed.get(r.vessel_key);\n    const pos = order.indexOf(r.vessel_key);\n    let width, value, sub, cls = \'\';\n    if (!revealed) {\n      width = r.distance_deg / maxDist;\n      value = `${r.distance_deg.toFixed(3)}°`;\n      sub = r.vessel_key === naiveKey ? \'nearest · proximity pick\' : null;\n      if (r.vessel_key === naiveKey) cls = \' is-naive\';\n    } else if (rep) {\n      width = rep.mean_iou;\n      value = rep.mean_iou.toFixed(3);\n      sub = `#${rep.rank} · best under ${rep.ensemble_win_count}/${rep.n_ensemble} variants`;\n      if (r.vessel_key === leadKey) cls = phase >= 3 ? \' is-lead is-settled\' : \' is-lead\';\n      else if (unknown) cls = \' is-below\';\n    } else {\n      width = 0;\n      value = \'—\';\n      sub = `not replayed · ${STATUS[status.get(r.vessel_key)] ?? \'filtered out\'}`;\n      cls = \' is-out\';\n    }\n    // struck only where replay names a different vessel; when it names no one, nothing is set aside\n    const struck = phase >= 1 && r.vessel_key === naiveKey && !agree && !unknown;\n    return (\n      <div key={r.vessel_key} className={`rv-row${cls}${struck ? \' is-struck\' : \'\'}`} role="row"\n           data-rank-key={r.vessel_key} id={`rank-${revealed ? \'replay\' : \'naive\'}-${r.vessel_key}`}\n           style={{ transform: `translateY(${pos * ROW}px)`, \'--w\': Math.max(0, Math.min(1, width)), \'--d\': pos }}>\n        <span className="rv-pos" role="cell">{pos + 1}</span>\n        <span className="rv-key" role="cell"><span className="rv-key-text">{r.vessel_key}</span></span>\n        <span className="rv-track" role="cell" aria-hidden="true">\n          <span className="rv-fill" />\n          {revealed && <span className="rv-gate" style={{ left: `${gate * 100}%` }} />}\n        </span>\n        <span className="rv-value" role="cell">{value}</span>\n        <span className="rv-sub" role="cell" key={`${phase >= 2}-${struck}`}>\n          {struck ? \'proximity pick · not supported by forward replay\'\n            : revealed && agree && r.vessel_key === naiveKey ? \'proximity and forward replay agree\'\n              : revealed && unknown && r.vessel_key === naiveKey ? `proximity pick · below the fit gate, like every candidate` : sub}\n        </span>\n      </div>\n    );\n  });\n\n  const badge = !revealed ? <Badge>proximity only</Badge>\n    : <Badge tone={unknown ? \'warning\' : \'accent\'}>{unknown ? \'abstained\' : \'named\'}</Badge>;\n  return (\n    <Card title="Naive vs Forward-Replay" badge={badge}\n          caption={revealed ? \'Which vessel’s drifted release best matches the slick.\' : \'The shortcut: the vessel nearest the slick when the image was taken.\'}\n          className={`rv-card${unknown && revealed ? \' is-abstain\' : \'\'}`}>\n      <div className="rv-controls">\n        {phase === 0\n          ? <button type="button" className="rv-btn is-primary" onClick={reveal}>Reveal forward-replay result</button>\n          : <button type="button" className="rv-btn" onClick={() => setPhase(0)}>Show proximity only</button>}\n        <span className="rv-legend">\n          {revealed ? <>Bar: mean IoU of the best replayed release · tick: fit gate {gate}</>\n            : <>Bar: distance to the slick when the image was taken · shorter is nearer</>}\n        </span>\n      </div>\n      <div className="rv-list" role="table" aria-label={revealed ? \'Vessels in forward-replay order\' : \'Vessels by distance at image time\'}\n           style={{ height: baseline.ranking.length * ROW }}>\n        {rows}\n      </div>\n      {revealed && unknown && (\n        <div className="rv-abstain" role="status">\n          <strong>No candidate meets the fit gate: the system abstains.</strong>\n          <span>The best replayed fit is a mean IoU of {attribution.ranking[0]?.mean_iou?.toFixed(3) ?? \'—\'}, below\n            the gate of {gate}. Declining to name a vessel is the output, not a failure to produce one.</span>\n        </div>\n      )}\n      <HowMeasured>\n        <dl>\n          <dt>Proximity</dt><dd>{C.baselineMethod}</dd>\n          <dt>Forward replay</dt><dd>{C.replayMethod}</dd>\n          <dt>Fit gate</dt><dd>Below a mean IoU of {gate} no vessel is named.</dd>\n          <dt>What the reveal does</dt><dd>It shows results the pipeline already computed; nothing is re-run.</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n'}, 'frontend/src/cards/ask.css': {'before': 'fbecabf51c8eb22c924be6666c6a08c8579d5b9e98ca65c8a18a9b5861c6f499', 'after': '/* Ask Slick Trace: readable exchanges, suggestion chips that stay, a rounded field */\n.console-panel .console-entry { margin-bottom: 10px; animation: ask-in 320ms cubic-bezier(0.22, 1, 0.36, 1); }\n.console-panel .console-q { font-size: var(--font-size-sm); }\n@keyframes ask-in { from { opacity: 0; translate: 0 6px; } }\n.ask-suggest { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0; }\n.ask-chip { padding: 6px 11px; border: 0; border-radius: 999px; cursor: default; font: inherit; font-size: var(--font-size-xs);\n            text-align: left; color: var(--label-1); background: var(--fill-pressed);\n            transition: background-color var(--dur-fast) ease, transform var(--dur-base) var(--ease-spring); }\n.ask-chip:hover { background: rgba(10, 132, 255, 0.16); }\n.ask-chip:active { transform: scale(0.97); }\n.ask-chip:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 1px; }\n.ask-chip:disabled { opacity: 0.5; }\n.ask-field { display: flex; align-items: center; gap: 6px; padding: 4px 4px 4px 14px; border-radius: 999px;\n             background: var(--fill-pressed); box-shadow: inset 0 0 0 0.5px var(--separator-strong);\n             transition: box-shadow var(--dur-fast) ease; }\n.ask-field:focus-within { box-shadow: inset 0 0 0 1px var(--accent), 0 0 0 4px var(--accent-ring); }\n.ask-field input { flex: 1; min-width: 0; height: 30px; border: 0; outline: none; background: transparent; font: inherit;\n                   font-size: var(--font-size-sm); color: var(--label-1); }\n.ask-field input::placeholder { color: var(--label-3); }\n.ask-send { flex: none; width: 30px; height: 30px; border: 0; border-radius: 50%; cursor: default; display: grid; place-items: center;\n            background: var(--accent); transition: transform var(--dur-base) var(--ease-spring), opacity var(--dur-fast) ease; }\n.ask-send svg { width: 14px; height: 14px; fill: none; stroke: #fff; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.ask-send:disabled { opacity: 0.35; }\n.ask-send:not(:disabled):active { transform: scale(0.92); }\n@media (prefers-reduced-motion: reduce) { .console-panel .console-entry { animation: none; } }\n\n/* Ask as a chat: the question at once, the reply arriving below it */\n.ask-chat { max-height: 340px; min-height: 120px; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding: 4px 2px 8px; }\n.ask-empty { margin: auto 0; text-align: center; font-size: var(--font-size-xs); color: var(--label-3); }\n.ask-ex { display: flex; flex-direction: column; gap: 6px; }\n.ask-q { align-self: flex-end; max-width: 88%; padding: 7px 12px; border-radius: 16px 16px 4px 16px; font-size: var(--font-size-sm);\n         color: #fff; background: var(--accent); animation: ask-pop 300ms cubic-bezier(0.22, 1.2, 0.36, 1) both; transform-origin: bottom right; }\n.ask-a { align-self: flex-start; max-width: 94%; padding: 9px 12px; border-radius: 16px 16px 16px 4px; font-size: var(--font-size-sm);\n         line-height: 1.5; color: var(--label-1); background: var(--fill-pressed); animation: ask-rise 380ms cubic-bezier(0.22, 1, 0.36, 1) both; }\n.ask-a p { margin: 4px 0 0; }\n.ask-a.is-pending { display: inline-flex; gap: 4px; padding: 11px 14px; }\n.ask-a.is-pending i { width: 6px; height: 6px; border-radius: 50%; background: var(--label-3); animation: ask-dot 1.1s ease-in-out infinite; }\n.ask-a.is-pending i:nth-child(2) { animation-delay: 0.15s; } .ask-a.is-pending i:nth-child(3) { animation-delay: 0.3s; }\n.ask-tag { display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); }\n.ask-tag.ok { color: var(--status-green); background: rgba(48, 209, 88, 0.14); }\n.ask-tag.refused { color: var(--status-orange); background: rgba(255, 159, 10, 0.14); }\n.ask-cites { display: block; margin-top: 6px; font-family: var(--font-mono); font-size: var(--font-size-xxs); color: var(--label-2); overflow-wrap: anywhere; }\n@keyframes ask-pop { from { opacity: 0; transform: scale(0.92) translateY(6px); } }\n@keyframes ask-rise { from { opacity: 0; transform: translateY(8px); } }\n@keyframes ask-dot { 0%, 80%, 100% { opacity: 0.3; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-3px); } }\n@media (prefers-reduced-motion: reduce) { .ask-q, .ask-a, .ask-a.is-pending i { animation: none; } }\n\n/* suggestions on one sideways-scrolling row, as in Messages, leaving the room to the chat */\n.ask-suggest { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; padding-bottom: 2px;\n               -webkit-mask-image: linear-gradient(90deg, #000 85%, transparent); mask-image: linear-gradient(90deg, #000 85%, transparent); }\n.ask-suggest::-webkit-scrollbar { display: none; }\n.ask-chip { flex: none; white-space: nowrap; }\n.ask-chat { max-height: none; flex: 1; }\n'}, 'frontend/src/cards/caseFinding.css': {'before': 'd5165e3ca0ca74d676a4e7996cf2b896f095ed592ab4d4532d7d9db13fdd68ab', 'after': '/* Case Finding: the named vessel beside its fit, three facts, the proximity pick set aside. */\n.cf2-hero { display: flex; align-items: center; gap: var(--space-6); padding: 18px 22px; border-radius: 18px;\n            background: radial-gradient(420px 220px at 85% 50%, rgba(10, 132, 255, 0.18), transparent 70%),\n                        linear-gradient(135deg, rgba(10, 132, 255, 0.10), rgba(100, 210, 255, 0.03));\n            box-shadow: inset 0 0 0 0.5px rgba(10, 132, 255, 0.35); }\n.cf2.is-abstain .cf2-hero { background: radial-gradient(420px 220px at 85% 50%, rgba(255, 159, 10, 0.16), transparent 70%),\n                                        linear-gradient(135deg, rgba(255, 159, 10, 0.08), rgba(255, 214, 10, 0.02));\n                            box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.4); }\n.cf2-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 6px; }\n.cf2-eyebrow { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.08em; color: var(--label-2); }\n.cf2-key { font-family: var(--font-mono); font-size: clamp(24px, 3vw, 36px); font-weight: 600; letter-spacing: -0.01em; line-height: 1.1;\n           overflow-wrap: anywhere; background: linear-gradient(90deg, #0a84ff, #64d2ff); -webkit-background-clip: text; background-clip: text; color: transparent; }\n.cf2.is-abstain .cf2-key { font-family: var(--font-display); background: none; color: var(--status-orange); }\n.cf2-why { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-2); max-width: 46ch; }\n\n.cf2-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 14px; }\n.cf2-tile { display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 12px 14px; border-radius: 14px; background: var(--fill-pressed); }\n.cf2-tile-label { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.06em; color: var(--label-3); }\n.cf2-tile-big { font-family: var(--font-display); font-size: 26px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.1; color: var(--label-1); font-variant-numeric: tabular-nums; }\n.cf2-tile-big small { font-size: 14px; font-weight: 500; color: var(--label-3); letter-spacing: 0; }\n.cf2-tile-sub { font-size: var(--font-size-xs); color: var(--label-2); }\n.cf2-tile-sub.is-warn { color: var(--status-orange); }\n.cf2-pips { display: flex; gap: 5px; margin-top: 2px; }\n.cf2-pips i { width: 9px; height: 9px; border-radius: 50%; background: var(--label-3); opacity: 0.4;\n              animation: cf-pip 420ms cubic-bezier(0.34, 1.56, 0.64, 1) backwards; animation-delay: calc(500ms + var(--i) * 70ms); }\n.cf2-pips i.is-won { background: #64d2ff; opacity: 1; box-shadow: 0 0 6px rgba(100, 210, 255, 0.7); }\n@keyframes cf-pip { from { transform: scale(0); } }\n\n.cf2-naive { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 12px; margin-top: 14px; padding: 10px 14px; border-radius: 12px;\n             box-shadow: inset 0 0 0 0.5px var(--separator-strong); }\n.cf2-naive-label { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.06em; color: var(--label-3); }\n.cf2-naive-key { position: relative; font-family: var(--font-mono); font-size: var(--font-size-md); color: var(--label-1); }\n.cf2-naive-key > span { position: relative; }\n.cf2-naive.is-struck .cf2-naive-key { color: var(--label-2); }\n.cf2-naive.is-struck .cf2-naive-key > span::after { content: ""; position: absolute; left: -2px; right: -2px; top: 54%; height: 1.5px; background: var(--status-orange);\n                                                    transform-origin: left; animation: cf-strike 520ms 700ms cubic-bezier(0.22, 1, 0.36, 1) backwards; }\n@keyframes cf-strike { from { transform: scaleX(0); } }\n.cf2-naive-sub { font-size: var(--font-size-xs); color: var(--label-2); }\n.cf2-foot { margin: 14px 0 0; font-size: var(--font-size-sm); color: var(--label-2); }\n@media (max-width: 900px) { .cf2-hero { flex-direction: column; align-items: flex-start; } .cf2-tiles { grid-template-columns: 1fr; } }\n@media (prefers-reduced-motion: reduce) { .cf2-pips i, .cf2-naive.is-struck .cf2-naive-key > span::after { animation: none; } }\n'}, 'frontend/src/cards/rankingReveal.css': {'before': '340b84a0657c2bcc3d0a4e6f8dea055f0b9edb06207beed0ee33de4b82ee1043', 'after': '/* Naive vs forward replay: rows positioned by transform so a re-sort animates. */\n\n.rv-controls { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }\n.rv-btn {\n  height: 32px; padding: 0 14px; border: 0; border-radius: 8px; cursor: default; font: inherit;\n  font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold);\n  background: var(--control-bg); color: var(--label-1); box-shadow: var(--shadow-control);\n  transition: transform var(--dur-base) var(--ease-spring), background-color var(--dur-fast) ease;\n}\n.rv-btn:hover { background: var(--control-bg-hover); }\n.rv-btn:active { transform: scale(0.97); }\n.rv-btn.is-primary { background: linear-gradient(135deg, #0a84ff, #3d9bff); color: #fff;\n                     box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.6), 0 6px 18px rgba(10, 132, 255, 0.35); }\n.rv-btn.is-primary:hover { background: linear-gradient(135deg, #2a95ff, #5aabff); }\n.rv-legend { font-size: var(--font-size-xs); color: var(--label-2); }\n\n.rv-list { position: relative; transition: height 400ms var(--ease-out); }\n.rv-row {\n  position: absolute; left: 0; right: 0; top: 0; height: 40px;\n  display: grid; grid-template-columns: 22px minmax(92px, 118px) minmax(80px, 1fr) 56px minmax(140px, 1.1fr);\n  align-items: center; gap: 12px; padding: 0 10px; border-radius: 9px;\n  transition: transform 720ms cubic-bezier(0.34, 1.26, 0.64, 1), opacity 300ms ease, background-color 300ms ease,\n              box-shadow 400ms ease, scale 400ms var(--ease-spring);\n}\n.rv-pos { font-family: var(--font-mono); font-size: var(--font-size-xs); color: var(--label-3); text-align: right; }\n.rv-key { position: relative; font-family: var(--font-mono); font-size: var(--font-size-sm); color: var(--label-1); }\n.rv-key-text { position: relative; }\n.rv-track { position: relative; height: 8px; border-radius: 4px; background: var(--fill-pressed); overflow: visible; }\n.rv-fill {\n  position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--w) * 100%); border-radius: 4px;\n  background: var(--label-3); transition: width 720ms cubic-bezier(0.34, 1.1, 0.64, 1), background-color 400ms ease;\n}\n.rv-gate { position: absolute; top: -5px; bottom: -5px; width: 2px; margin-left: -1px; border-radius: 1px;\n           background: var(--status-orange); animation: rv-in 400ms 500ms ease both; }\n.rv-value { font-family: var(--font-mono); font-size: var(--font-size-sm); font-variant-numeric: tabular-nums; text-align: right; color: var(--label-1); }\n.rv-sub { font-size: var(--font-size-xs); color: var(--label-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n/* before the reveal: the proximity pick */\n.rv-row.is-naive { background: rgba(255, 159, 10, 0.1); box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.45); }\n.rv-row.is-naive .rv-fill { background: var(--status-orange); }\n\n/* the reveal: the proximity pick is struck through where replay does not support it */\n.rv-row.is-struck { opacity: 0.55; }\n.rv-row.is-struck .rv-key-text::after {\n  content: ""; position: absolute; left: -2px; right: -2px; top: 52%; height: 1.5px; background: var(--status-orange);\n  transform-origin: left; animation: rv-strike 360ms var(--ease-out) forwards;\n}\n.rv-row.is-struck .rv-sub { color: var(--status-orange); }\n@keyframes rv-strike { from { transform: scaleX(0); } to { transform: scaleX(1); } }\n\n/* forward replay\'s fit, and its leader */\n.rv-list .rv-row .rv-fill { background: linear-gradient(90deg, rgba(90, 200, 250, 0.55), rgba(90, 200, 250, 0.85)); }\n.rv-row.is-naive .rv-fill { background: var(--status-orange) !important; }\n.rv-row.is-out { opacity: 0.45; }\n.rv-row.is-lead { background: rgba(10, 132, 255, 0.12); box-shadow: inset 0 0 0 0.5px rgba(10, 132, 255, 0.55); }\n.rv-row.is-lead .rv-fill { background: linear-gradient(90deg, #0a84ff, #5ac8fa); }\n.rv-row.is-lead.is-settled { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.7), 0 0 26px rgba(10, 132, 255, 0.28);\n                              animation: rv-glow 2.6s ease-in-out 1; }\n.rv-row.is-lead .rv-key, .rv-row.is-lead .rv-value { font-weight: var(--font-weight-semibold); }\n.rv-row.is-lead .rv-sub { color: var(--accent); }\n@keyframes rv-glow { 0%, 100% { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.7), 0 0 14px rgba(10, 132, 255, 0.2); }\n                     40% { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.9), 0 0 34px rgba(10, 132, 255, 0.45); } }\n@keyframes rv-in { from { opacity: 0; } }\n\n/* when the system abstains: muted ranking, an explicit statement */\n.rv-card.is-abstain .rv-row .rv-fill { background: var(--label-3); }\n.rv-card.is-abstain .rv-row { opacity: 0.6; }\n.rv-card.is-abstain .rv-gate { box-shadow: 0 0 8px rgba(255, 159, 10, 0.8); }\n.rv-abstain { display: flex; flex-direction: column; gap: 4px; margin-top: 14px; padding: 12px 14px; border-radius: 10px;\n              background: rgba(255, 159, 10, 0.1); box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.5);\n              font-size: var(--font-size-sm); color: var(--label-1); animation: rv-in 400ms 600ms ease both; }\n.rv-abstain strong { color: var(--status-orange); }\n.rv-note { margin: 14px 0 0; font-size: var(--font-size-sm); color: var(--label-2); animation: rv-in 400ms ease both; }\n\n@media (prefers-reduced-motion: reduce) {\n  .rv-row, .rv-fill, .rv-list { transition: none; }\n  .rv-row.is-struck .rv-key-text::after, .rv-row.is-lead.is-settled, .rv-gate, .rv-abstain, .rv-note { animation: none; }\n}\n@media (max-width: 760px) { .rv-row { grid-template-columns: 18px 92px 1fr 50px; } .rv-sub { display: none; } }\n\n/* a row reached from the map flashes once */\n.rv-row.is-flash { animation: row-flash 1.8s var(--ease-out); }\n\n/* a smoother reveal: rows glide with a decelerating curve (no overshoot), staggered by\n   their new position; bars ease to their new length on the same curve; labels cross-fade */\n.rv-row { transition: transform 780ms cubic-bezier(0.22, 1, 0.36, 1), opacity 320ms ease, background-color 360ms ease, box-shadow 420ms ease;\n          transition-delay: calc(var(--d, 0) * 38ms); }\n.rv-fill { transition: width 820ms cubic-bezier(0.22, 1, 0.36, 1), background-color 420ms ease; transition-delay: calc(80ms + var(--d, 0) * 38ms); }\n.rv-sub { animation: rv-sub-in 420ms ease both; animation-delay: calc(160ms + var(--d, 0) * 38ms); }\n@keyframes rv-sub-in { from { opacity: 0; translate: 6px 0; } }\n@media (prefers-reduced-motion: reduce) { .rv-row, .rv-fill { transition: none; } .rv-sub { animation: none; } }\n'}}
CL_OLD = 'exact 3 x 3), dropping to two or one only on narrow windows.\n'
CL_NEW = 'exact 3 x 3), dropping to two or one only on narrow windows.\n\n**Batch 1 of the card redesign.** Case Finding is rebuilt: the named vessel beside its fit gauge,\nthree fact tiles (variants won, lead over the runner-up, time inside the origin area) and the\nproximity pick set aside on its own row - with every text column free to wrap, so nothing leaves\nthe card (checked in all nine cases). The reveal drops its closing sentence and glides: rows and\nbars ease on a decelerating curve, staggered, and labels cross-fade. The Conclusion Graph loses\nits stage-count badge. Ask behaves like a chat: a tapped or typed question appears at once, a\ntyping indicator follows, and the reply arrives below it; suggestions sit on one scrolling row.\n'
